3	import com.maritime.platform.gateway.security.RouteSecurityPolicy;
4	import com.maritime.platform.gateway.security.RouteSecurityPolicyResolver;
5	
6	import org.springframework.cloud.gateway.filter.GatewayFilterChain;
7	import org.springframework.cloud.gateway.filter.GlobalFilter;
8	import org.springframework.core.Ordered;
9	import org.springframework.core.annotation.Order;
10	import org.springframework.stereotype.Component;
11	import org.springframework.web.server.ServerWebExchange;
12	
13	import reactor.core.publisher.Mono;
14	
15	/**
16	 * Resolves the {@link RouteSecurityPolicy} for every request and stores it
17	 * in an exchange attribute so downstream filters and handlers can make
18	 * auth decisions without re-resolving.
19	 * <p>
20	 * Passing the request through to the downstream chain unconditionally;
21	 * the auth-mode enforcement itself is implemented in later tasks.
22	 */
23	@Component
24	@Order(GatewayFilterOrder.SECURITY_POLICY)
25	public class RouteSecurityPolicyFilter implements GlobalFilter, Ordered {
26	
27		public static final String POLICY_ATTR = "gateway.securityPolicy";
28	
29		private final RouteSecurityPolicyResolver resolver;
30	
31		public RouteSecurityPolicyFilter(RouteSecurityPolicyResolver resolver) {
32			this.resolver = resolver;
33		}
34	
35		@Override
36		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
37			RouteSecurityPolicy policy = resolver.resolve(exchange.getRequest());
38			exchange.getAttributes().put(POLICY_ATTR, policy);
39			return chain.filter(exchange);
40		}
41	
42		@Override
43		public int getOrder() {
44			return GatewayFilterOrder.SECURITY_POLICY;
45		}
46	}
