20	import org.springframework.http.server.reactive.ServerHttpRequestDecorator;
21	import org.springframework.stereotype.Component;
22	import org.springframework.web.server.ServerWebExchange;
23	
24	import reactor.core.publisher.Flux;
25	import reactor.core.publisher.Mono;
26	
27	/**
28	 * Authenticates system-to-system requests using HMAC-SHA256 signatures.
29	 * <p>
30	 * Reads the request body once to compute the SHA-256 digest, then caches it
31	 * in a decorated exchange so downstream filters and handlers can still read it.
32	 * Stores the mapped {@link GatewayPrincipal.App} in the exchange.
33	 */
34	@Component
35	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
36	@Order(GatewayFilterOrder.HMAC_AUTHENTICATION)
37	public class HmacAuthenticationGatewayFilter implements GlobalFilter, Ordered {
38	
39		private final HmacAuthenticationManager authManager;
40		private final GatewaySecurityProperties properties;
41		private final GatewayErrorWriter errorWriter;
42	
43		public HmacAuthenticationGatewayFilter(HmacAuthenticationManager authManager,
44				GatewaySecurityProperties properties, GatewayErrorWriter errorWriter) {
45			this.authManager = authManager;
46			this.properties = properties;
47			this.errorWriter = errorWriter;
48		}
49	
50		@Override
51		public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
52			RouteSecurityPolicy policy = exchange.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
53			if (!requiresHmac(policy)) {
54				return chain.filter(exchange);
55			}
56	
57			GatewaySecurityProperties.Headers hdrs = properties.getHmac().getHeaders();
58			String appKey = exchange.getRequest().getHeaders().getFirst(hdrs.getAppKey());
59			String timestamp = exchange.getRequest().getHeaders().getFirst(hdrs.getTimestamp());
60			String nonce = exchange.getRequest().getHeaders().getFirst(hdrs.getNonce());
61			String bodyDigest = exchange.getRequest().getHeaders().getFirst(hdrs.getBodyDigest());
62			String signature = exchange.getRequest().getHeaders().getFirst(hdrs.getSignature());
63	
64			if (isAnyBlank(appKey, timestamp, nonce, bodyDigest, signature)) {
65				return errorWriter.write(exchange, GatewayAuthErrorCode.MISSING_HMAC_HEADERS);
66			}
67	
68			return readAndCacheBody(exchange)
69					.flatMap(cachedExchange -> {
70						byte[] bodyBytes = cachedExchange.getAttribute("gateway.cachedBody");
71						String method = exchange.getRequest().getMethod().name();
72						String rawPath = exchange.getRequest().getURI().getRawPath();
73						String rawQuery = exchange.getRequest().getURI().getRawQuery();
74	
75						return authManager.authenticate(appKey, timestamp, nonce, bodyDigest, signature,
76										method, rawPath, rawQuery, bodyBytes != null ? bodyBytes : new byte[0])
77								.flatMap(principal -> {
78									cachedExchange.getAttributes().put(GatewayPrincipal.ATTRIBUTE, principal);
79									return chain.filter(cachedExchange);
80								})
81								.onErrorResume(JwtAuthenticationException.class,
82										e -> errorWriter.write(cachedExchange, e.getErrorCode()));
83					});
84		}
85	
86		@Override
87		public int getOrder() {
88			return GatewayFilterOrder.HMAC_AUTHENTICATION;
89		}
90	
91		/**
92		 * Reads the request body once, caches the bytes, and returns a decorated exchange
93		 * whose request body can be re-read by downstream filters and handlers.
94		 */
95		private Mono<ServerWebExchange> readAndCacheBody(ServerWebExchange exchange) {
96			return DataBufferUtils.join(exchange.getRequest().getBody())
97					.map(buf -> {
98						byte[] bytes = new byte[buf.readableByteCount()];
99						buf.read(bytes);
100						DataBufferUtils.release(buf);
101						return bytes;
102					})
103					.switchIfEmpty(Mono.just(new byte[0]))
104					.map(bytes -> {
105						ServerHttpRequest decorated = new ServerHttpRequestDecorator(exchange.getRequest()) {
106							@Override
107							public Flux<DataBuffer> getBody() {
108								return Flux.just(
109										exchange.getResponse().bufferFactory().wrap(bytes));
110							}
111						};
112						ServerWebExchange cached = exchange.mutate().request(decorated).build();
113						cached.getAttributes().put("gateway.cachedBody", bytes);
114						return cached;
115					});
116		}
117	
118		private boolean requiresHmac(RouteSecurityPolicy policy) {
119			if (policy == null) {
120				return false;
121			}
122			AuthMode mode = policy.getAuthMode();
123			return mode == AuthMode.HMAC || mode == AuthMode.JWT_OR_HMAC || mode == AuthMode.JWT_AND_HMAC;
124		}
125	
126		private boolean isAnyBlank(String... values) {
127			for (String v : values) {
128				if (v == null || v.isBlank()) {
129					return true;
130				}
131			}
132			return false;
133		}
134	
135	}
