				.expiration(Date.from(now.plus(1, ChronoUnit.HOURS)))
				.signWith(signingKey)
				.compact();
	}

	private static GatewayFilterChain capturingChain(AtomicReference<ServerWebExchange> ref) {
		return exchange -> {
