					.verifyComplete();

			String body = exchange.getResponse().getBodyAsString().block();
			assertThat(body).contains(GatewayAuthErrorCode.MISSING_HMAC_HEADERS);
			assertThat(exchange.getResponse().getStatusCode().value()).isEqualTo(401);
		}

		@Test
