			assertThat(body).contains(GatewayAuthErrorCode.MISSING_HMAC_HEADERS);
		}
	}

	// ---------- error propagation from manager ----------

	@Nested
	@DisplayName("Error propagation from authentication manager")
	class ErrorPropagation {

		@Test
