	// ---------- JWT_AND_HMAC reserved mode ----------

	@Nested
	@DisplayName("JWT_AND_HMAC reserved mode")
	class JwtAndHmacReserved {

		@Test
		@DisplayName("JWT_AND_HMAC returns UNSUPPORTED_AUTH_MODE with 501")
