                assertThat(app.getAppKey()).isEqualTo("demo-key");
                assertThat(app.getAppSecret()).isEqualTo("demo-secret");
                assertThat(app.getAppCode()).isEqualTo("demo");
                assertThat(app.isEnabled()).isTrue();
